from __future__ import annotations

import argparse
import json
import re
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


SCHEMA = "job_request_v0"


def utc_ts() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def fail(msg: str, code: int = 1) -> int:
    print(json.dumps({"schema": SCHEMA, "ok": False, "exit_code": code, "ts_utc": utc_ts(), "error": msg}, ensure_ascii=False))
    return code


def validate(data: dict[str, Any]) -> tuple[bool, str | None]:
    if data.get("schema") != SCHEMA:
        return False, "schema must be job_request_v0"

    pid = data.get("product_id")
    if not isinstance(pid, str) or not re.fullmatch(r"[a-z0-9_\-]{3,80}", pid):
        return False, "product_id must match [a-z0-9_\-]{3,80}"

    req = data.get("requirements")
    if not isinstance(req, str) or len(req.strip()) < 10:
        return False, "requirements must be a non-empty string (>=10 chars)"

    # optional: allowed file edits (whitelist)
    allowed = data.get("allowed_paths")
    if allowed is not None:
        if not isinstance(allowed, list) or not all(isinstance(x, str) for x in allowed):
            return False, "allowed_paths must be an array of strings"

    return True, None


def main() -> int:
    ap = argparse.ArgumentParser(description="Validate job_request_v0 JSON")
    ap.add_argument("--in", dest="inp", required=True)
    args = ap.parse_args()

    p = Path(args.inp)
    if not p.exists():
        return fail(f"input not found: {p}", 2)

    try:
        data = json.loads(p.read_text(encoding="utf-8-sig"))
    except Exception as e:  # noqa: BLE001
        return fail(f"invalid json: {e}", 1)

    ok, err = validate(data)
    if not ok:
        return fail(err or "invalid job_request", 1)

    print(json.dumps({"schema": SCHEMA, "ok": True, "exit_code": 0, "ts_utc": utc_ts(), "product_id": data["product_id"]}, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

from __future__ import annotations

import argparse
import json
import subprocess
import sys
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


SCHEMA = "workspace_gate_v0"


def utc_ts() -> str:
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")


def run(cmd: list[str], cwd: Path | None = None) -> dict[str, Any]:
    p = subprocess.run(cmd, cwd=str(cwd) if cwd else None, capture_output=True, text=True, check=False)
    return {"cmd": cmd, "rc": p.returncode, "stdout": p.stdout or "", "stderr": p.stderr or ""}


def py_compile_tree(root: Path) -> dict[str, Any]:
    import py_compile

    py_files = sorted(root.rglob("*.py"))
    errors: list[dict[str, str]] = []
    for f in py_files:
        try:
            py_compile.compile(str(f), doraise=True)
        except Exception as e:  # noqa: BLE001
            errors.append({"file": str(f), "error": repr(e)})
    return {"files": [str(p) for p in py_files], "errors": errors, "ok": len(errors) == 0}


def main() -> int:
    ap = argparse.ArgumentParser(description="Gate a workspace (py_compile + ruff)")
    ap.add_argument("--workspace", required=True)
    args = ap.parse_args()

    ws = Path(args.workspace).resolve()
    if not ws.exists():
        raise FileNotFoundError(f"workspace not found: {ws}")

    checks: dict[str, Any] = {}
    checks["py_compile"] = py_compile_tree(ws)
    checks["ruff"] = run([sys.executable, "-m", "ruff", "check", str(ws)])

    ok = bool(checks["py_compile"]["ok"]) and checks["ruff"]["rc"] == 0

    out = {"schema": SCHEMA, "ok": ok, "exit_code": 0 if ok else 1, "ts_utc": utc_ts(), "workspace": str(ws), "checks": checks}
    print(json.dumps(out, ensure_ascii=False))
    return out["exit_code"]


if __name__ == "__main__":
    raise SystemExit(main())

